function pxShade(hex,amt){ hex=(hex||'#888888').replace('#',''); if(hex.length<6) hex='888888';
  const f=v=>Math.max(0,Math.min(255,parseInt(v,16)+amt)).toString(16).padStart(2,'0');
  return '#'+f(hex.slice(0,2))+f(hex.slice(2,4))+f(hex.slice(4,6)); }
